    fun forBook(bookCode: String): List<TocNode> = trees[bookCode] ?: emptyList()

    fun packTitle(packId: String): String? {
        fun walk(nodes: List<TocNode>): String? {
            for (node in nodes) {
                if (node.packId == packId) return node.title
                walk(node.children)?.let { return it }
            }
            return null
        }
        return trees.values.firstNotNullOfOrNull { walk(it) }
    }

    fun pdfFileName(packId: String): String? {
        fun walk(nodes: List<TocNode>): String? {
            for (node in nodes) {
                if (node.packId == packId) return node.pdfFileName
                walk(node.children)?.let { return it }
            }
            return null
        }
        return trees.values.firstNotNullOfOrNull { walk(it) }
    }

    fun allPacksForBook(bookCode: String): List<TocNode> {
        val out = mutableListOf<TocNode>()
        fun walk(nodes: List<TocNode>) {
            for (n in nodes) {
                if (n.packId != null) out.add(n)
                walk(n.children)
            }
        }
        walk(forBook(bookCode))
        return out
    }
